		{ text = "Conquistando Aceitação" },
	},
	bonds = {
		{ id = "master-smith-burninate", name = "Mestre Ferreiro Burninate", note = "guardião da forja da Irmandade" },
		{ id = "lookout-captain-lolo-longstriker", name = "Capitão dos Vigias Lolo Longstriker", note = "capitão de seus vigias" },
		{ id = "overseer-maltorius", name = "Supervisor Maltorius", note = "o traidor que ele quer morto" },
		{ id = "lokhtos-darkbargainer", name = "Lokhtos Darkbargainer", note = "o agente da Irmandade no Abismo" },
