})

Translate("ptBR", "master-smith-burninate", {
	title = "Mestre Ferreiro Burninate",
	subtitle = "Ferreiro da Irmandade do Tório",
	found = "Na forja do Posto de Tório",
	hint = "Encontre o ferreiro que cuida da forja do Posto de Tório.",
	allegiance = "Irmandade do Tório",
