Translate("ptBR", "velarok-windblade", {
	title = "Velarok Windblade",
	subtitle = "Um Homem Jurado à Vingança",
	found = [=[Ao sul do Posto de Tório, ao lado dos restos mutilados de anões Ferro Negro]=],
	hint = [=[Procure o estranho que espera entre os Ferro Negro mortos, ao sul do Posto de Tório.]=],
	allegiance = "Sua própria causa",
	aliases = { "Velarok", "Kalaran Windblade" },
	sections = {
		{
			title = "Resumo",
			text = [=[Velarok Windblade veio à {link:searing-gorge}Garganta Abrasadora{/link} em busca de vingança, ou assim ele diz. Fala de um pai morto pelos {link:dark-iron-dwarves}Ferro Negro{/link} do {link:the-cauldron}Caldeirão{/link}, e de pedidos de justiça que os magistrados de {link:stormwind-city}Ventobravo{/link} não quiseram ouvir. O reino, diz ele com amargura, prefere fingir que este canto do mundo não existe a mandar seus soldados para cá. Por isso veio ele mesmo, sem outra companhia além de um escudeiro desajeitado, e espera alguém ousado o bastante para ajudá-lo a atacar.]=],
		},
		{
			title = "Importância",
			text = [=[Velarok oferece o que a garganta raramente oferece: um plano. Ele não pretende enfrentar os {link:dark-iron-dwarves}Ferro Negro{/link} lâmina contra lâmina. Pretende primeiro cegá-los, queimando as torres de sentinela que guardam {link:the-cauldron}o Caldeirão{/link}, e então atacar antes que possam se recuperar. Aos que o ajudarem, promete riquezas além de seus sonhos.]=],
		},
		{
			title = "Feitos",
			text = [=[• Conta sua história a qualquer viajante disposto a ouvir.
• Reúne corações de chama e óleo de golem para uma tocha que nenhum elemento consegue apagar.
• Desmancha as adagas de tório dos escravagistas {link:dark-iron-dwarves}Ferro Negro{/link} para forjar o cabo da tocha.
• Extrai a magia de um símbolo de {red:ragnaros}Ragnaros{/red}, tomado do {link:twilight-s-hammer}Martelo do Crepúsculo{/link}, para formar seu invólucro.]=],
		},
	},
	chapters = {
		{
			title = "A Tocha da Retribuição",
			hint = [=[Reúna o que Velarok precisa para sua tocha, e veja-a ser feita.]=],
			text = [=[A tocha foi feita da própria garganta. Sua chama veio dos corações de elementais de fogo e do óleo de golens de guerra. Seu cabo foi forjado com o tório encantado das próprias lâminas dos escravagistas. Seu invólucro foi trabalhado a partir de um ídolo do Senhor do Fogo, cuja magia imunda Velarok julgou perfeita para a tarefa. Ele se debruçou sobre as peças por muito tempo, e pediu paciência a seu ajudante. Quando terminou, quem erguia a tocha sentia ondas de ódio e raiva passarem por si.]=],
		},
		{
			title = "O Enganador",
			hint = "Incendeie as quatro torres do Caldeirão.",
			text = [=[As torres arderam, e o escudeiro de Velarok gritou que era glorioso. Então Velarok abandonou a forma de homem. Era um draco da revoada negra, e nunca houvera pai assassinado nenhum. Ele só precisava que a primeira linha de defesa dos {link:dark-iron-dwarves}Ferro Negro{/link} fosse destruída, e sabia que nenhum mortal ajudaria a legião da {link:blackrock-clan}Rocha Negra{/link} se lhe pedissem às claras. Poupou os que o haviam servido, para que vivessem para ver o caos da invasão da garganta que estava por vir. Deixou-lhes um tesouro de bugigangas e, com ele, a muda de um dragão negro, que, segundo disse, seus parentes nas {link:burning-steppes}Estepes Ardentes{/link} poderiam usar para fortalecer seu ofício. Então alçou voo rumo à {link:blackrock-mountain}Montanha Rocha Negra{/link}.]=],
		},
	},
	mentions = {
		{ text = "Retribuição Divina" },
		{ text = "A Chama Perfeita" },
		{ text = "Forjando o Cabo" },
		{ text = "O Invólucro da Chama" },
		{ text = "A Tocha da Retribuição" },
		{ text = "A Tocha da Retribuição, ligada a quem a porta" },
		{ text = "{link:squire-maltrake}Escudeiro Maltrake{/link}" },
		{ text = "Incendeie-as!" },
		{ text = "Bugigangas..." },
	},
	bonds = {
		{ id = "squire-maltrake", name = "Escudeiro Maltrake", note = "seu servo" },
	},
})

Translate("ptBR", "squire-maltrake", {
	title = "Escudeiro Maltrake",
	subtitle = "Escudeiro de Velarok Windblade",
	found = "Ao lado de Velarok Windblade, ao sul do Posto de Tório",
	hint = "Fale com o escudeiro que está ao lado de Velarok Windblade.",
	allegiance = "Seu senhor",
	aliases = { "Maltrake" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Escudeiro Maltrake segue {link:velarok-windblade}Velarok Windblade{/link}, e vive, como diz, apenas para servir a seu senhor. Velarok o chama de palerma desajeitado. É Maltrake quem explica como a Tocha da Retribuição deve ser usada: levada a cada uma das quatro torres de sentinela do {link:the-cauldron}Caldeirão{/link} e acesa lá dentro, para que ardam por muito tempo e nenhuma sentinela possa mantê-las.]=],
