			text = [=[Por ordem de seu senhor, Maltrake depôs um baú trancado a seus próprios pés para os que haviam acendido as torres. Ele perguntara o que devia ser feito com eles, já que não tinham mais utilidade. Seu senhor o calou, e os deixou viver.]=],
		},
	},
	mentions = {
		{ text = "Escudeiro Maltrake" },
		{ text = "Incendeie-as!" },
		{ text = "Bugigangas..." },
	},
	bonds = {
		{ id = "velarok-windblade", name = "Velarok Windblade", note = "seu senhor" },
	},
})

Translate("ptBR", "dorius-stonetender", {
	title = "Dorius Stonetender",
	subtitle = "Arqueólogo de Altaforja",
	found = "O fundo da Escavação Pedrassuja",
	hint = "Procure o anão ferido no fundo da escavação de Pedrassuja.",
	allegiance = "Reino de Altaforja",
	aliases = { "Dorius" },
	sections = {
		{
			title = "Resumo",
			text = [=[Dorius Stonetender liderou uma equipe de escavação de Altaforja na {link:searing-gorge}Garganta Abrasadora{/link}. Seu irmão é o Curador Thorius, do Salão dos Exploradores. Quando os {link:dark-iron-dwarves}Ferro Negro{/link} vieram, sua equipe foi capturada, e Dorius ficou ferido e sangrando no poço de {link:grimesilt-dig-site}Pedrassuja{/link}. Ele implora a qualquer estranho que passe que o ajude a chegar ao portão de {link:loch-modan}Loch Modan{/link} e à estrada de volta para {link:ironforge}Altaforja{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Dorius foi em busca das pedras chamadas Suntara, relíquias que os {link:dark-iron-dwarves}Ferro Negro{/link} também desejavam. Seu destino põe o irmão enlutado num caminho de vingança, e arrasta {link:ironforge}Altaforja{/link} para os segredos do {link:the-cauldron}Caldeirão{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Liderou uma equipe de arqueologia de {link:ironforge}Altaforja{/link} na garganta.
• Marcou {link:the-cauldron}o Caldeirão{/link} para que seus homens não se perdessem ali para sempre.
• Abriu caminho à força até o portão da {link:dustfire-valley}Galeria Lapidada{/link}, apesar dos ferimentos.]=],
		},
	},
	chapters = {
		{
			title = "A Carta Chamuscada",
			hint = [=[Ajude Dorius a chegar à segurança, e leve o que ele deixar para trás.]=],
			text = [=[Dorius não chegou ao portão. Um tiro soou quando a passagem surgiu à vista, e ele caiu. Deixou para trás uma carta, chamuscada nas bordas, endereçada ao irmão. Nela escreveu que as pedras eram reais, que os {link:dark-iron-dwarves}Ferro Negro{/link} as tinham, e que o líder deles, Lathoric, o Negro, usava seu poder para escravizar a equipe de escavação. Os homens tinham sido levados ao {link:the-cauldron}Caldeirão{/link}. Suas mentes estavam torcidas para uma única tarefa: a construção de algo chamado {link:obsidion}Obsidion{/link}. Libertem-nos, pediu ele. Quando Thorius a leu, chorou, e em nome da Luz jurou que o último desejo do irmão seria cumprido.]=],
		},
		{
			title = "O Altar de Suntara",
			hint = "Desça ao Fosso de Lava em busca dos homens de Dorius.",
			text = [=[Os arqueólogos foram encontrados no fundo do {link:the-slag-pit}Fosso de Lava{/link}, ainda trabalhando, embora seus corpos estivessem falhando. Um deles, moribundo, explicou que o poder da Suntara os levaria a terminar sua tarefa mesmo depois da morte. Só o altar de Suntara poderia libertá-los, e faltava-lhe uma relíquia que o {link:twilight-s-hammer}Martelo do Crepúsculo{/link} guardava nas colinas do {link:firewatch-ridge}Cerro da Sentinela de Fogo{/link}. A relíquia foi tomada dos cultistas e posta sobre o altar.]=],
		},
		{
			title = "Lathoric, o Negro",
			hint = "Veja o que o altar de Suntara desperta.",
			text = [=[Tudo não passara de uma armadilha. Dorius nunca morrera. Quando encontrou as pedras Suntara em {link:grimesilt-dig-site}Pedrassuja{/link}, o poder de {red:ragnaros}Ragnaros{/red} o percorreu, e o Senhor do Fogo lhe deu um novo propósito e um novo nome: Lathoric, o Negro. Ele se aproveitara da dor do irmão para atrair salvadores à garganta, para que eles recuperassem em seu nome a última pedra das mãos do {link:twilight-s-hammer}Martelo do Crepúsculo{/link}. {link:obsidion}Obsidion{/link} fora construído pela vontade do Senhor do Fogo, gabou-se ele, para destruir os orcs do Pico da {link:blackrock-mountain}Rocha Negra{/link} e uni-lo a seus irmãos nas profundezas ardentes. Então ordenou que o golem se erguesse. Quando Thorius soube da verdade, seu rosto empalideceu. O irmão traíra a ele e a toda {link:ironforge}Altaforja{/link}, e Thorius temia que, se um {link:dwarves}anão{/link} tão nobre podia ser corrompido tão facilmente, ninguém estava seguro.]=],
		},
	},
	mentions = {
		{ text = "Pedras de Suntara" },
		{ text = "Pedras de Suntara, a carta chamuscada" },
		{ text = "Justiça Anã" },
		{ text = "Libertem-nos" },
		{ text = "Levante-se, {link:obsidion}Obsidion{/link}!" },
	},
	bonds = {
		{ id = "curator-thorius", name = "Curador Thorius", note = "seu irmão" },
		{ id = "obsidion", name = "Obsidion", note = "o golem que seus homens foram obrigados a construir" },
	},
})

