Translate("ptBR", "zamael-lunthistle", {
	title = "Zamael Lunthistle",
	subtitle = "Espírito da Jaula",
	found = [=[Numa jaula na colina do Martelo do Crepúsculo, a noroeste do Cerro da Sentinela de Fogo]=],
	hint = [=[Suba ao acampamento do culto no Cerro da Sentinela de Fogo e olhe dentro de sua jaula.]=],
	allegiance = "Eluna",
	aliases = { "Zamael" },
	sections = {
		{
			title = "Resumo",
			text = [=[Zamael Lunthistle é o fantasma de um {link:night-elves}elfo noturno{/link}, preso numa jaula pelo {link:twilight-s-hammer}Martelo do Crepúsculo{/link}. Quando jovem, na {link:darkshore}Costa Negra{/link}, ele se juntou ao culto, abandonou {red:elune}Eluna{/red} e passou a cultuar os {red:old-gods}Deuses Antigos{/red}. Muitos anos depois, uma visão da deusa o despertou. Arrependido, começou uma prece a Eluna numa tábua de ouro puro. O culto a encontrou, declarou-o blasfemo e o matou antes que a prece estivesse terminada. Seu espírito não consegue partir. O culto o mantém enjaulado como aviso.]=],
		},
	},
	chapters = {
